{
  "Mục": "Dự trữ tài nguyên và hệ thống kinh tế của Phần Thiên Các",
  "Kênh tài nguyên": "Toàn bộ nguồn tài nguyên nhập vào do Ám thương Hoắc Khỉ La lo liệu. Nàng dùng mấy chục thân phận kinh doanh cửa tiệm hợp pháp và kênh phi pháp ở các đại phường thị, chợ đen và thương hội bí mật, mạng lưới phủ Trung Ương Thần Châu, Nam Ly Hỏa Châu và Đông Cực Thanh Mộc Vực; Vạn Bảo Lầu, Hắc Kim Các và một số thương hội phụ thuộc tông môn chính đạo đều qua lại với nàng mà không hề hay biết",
  "Ước tính dự trữ": {
    "Linh thạch": "Cực phẩm tính bằng nghìn, thượng phẩm tính bằng chục vạn, nguồn từ tích lũy lâu năm của thương lộ ngầm và khai thác bí mật các mạch khoáng bỏ hoang",
    "Đan dược": "Liễu Nhứ Vãn (loại hệ độc/phụ trợ chiến đấu) và Tiết Ánh Hàn (loại phá cảnh/hồi phục chính thống) phân công luyện chế nhập kho. Tỷ lệ thành đan của đan dược đột phá chính thống (Hóa Anh Đan đến Hư Linh Đan) tăng từ bốn thành của Liễu Nhứ Vãn lên tám thành rưỡi của Tiết Ánh Hàn, phẩm chất sản lượng mỗi lò ổn định.",
    "Công pháp": "Mật thất tàng kinh tầng giữa Vương Tọa Tháp lưu giữ mười bảy bộ công pháp Thiên giai, hơn trăm bộ Địa giai, phần lớn do Ân Vô Quy tìm kiếm từ phế tích và cấm địa",
    "Pháp bảo": "Bảy món Tiên Thiên Linh Bảo cấp phát cho thành viên cốt lõi, hơn ba mươi món Thông Thiên Linh Bảo trang bị cho ám vệ tử sĩ, Cổ bảo tính bằng hàng trăm"
  },
  "Quản lý hậu cần": "Vật tư trong vực do Hữu sứ Liễu Nhứ Vãn toàn quyền phân phối, hạn mức tu luyện của thành viên cốt lõi được điều chỉnh động theo tu vi hiện tại, cống hiến nhiệm vụ và nhu cầu đột phá, Ân Vô Quy có quyền phê duyệt cuối cùng"
}

34.content:
{
  "Mục": "Mạng lưới hiệp lực vòng ngoài của Phần Thiên Các",
  "Tổng tắc": "Người hiệp lực đều không biết Phần Thiên Các tồn tại, chỉ qua lại với một thân phận thương nghiệp nào đó của Hoắc Khỉ La. Các cá thể cách ly tuyệt đối, không biết nhau. Kênh bại lộ thì cắt đứt và xây lại bằng thân phận mới. Nếu có người hiệp lực tiếp xúc thông tin vượt phạm vi nên biết, do Kỳ Vô U dùng thuật cải viết linh hồn xóa ký ức liên quan từ xa, mục tiêu hoàn toàn không hay biết",
  "Năm loại người hiệp lực": {
    "Đối tác thương nghiệp": "Hơn 30 cửa tiệm phường thị (giao dịch linh tài, đan dược, pháp khí, thông tin), cung cấp kênh thu mua hợp pháp, tình báo thị trường và thông tin dòng người",
    "Kẻ buôn tin tình báo": "Hơn 10 tay môi giới hệ Hắc Kim Các, mua theo lần các tin vụn vặt để bổ sung điểm mù cho mạng ám tử; không bao giờ mua liên tiếp quá ba lần cùng loại tình báo ở cùng một người, phòng họ đem chính hành vi mua bán ra bán",
    "Tán tu đánh thuê": "Lưu động không cố định, qua bảng treo thưởng nhận ủy thác thông thường (vận chuyển, khảo sát, săn giết), tạo tiếng ồn yểm hộ cho nhiệm vụ thật",
    "Kênh buôn chợ đen": "5 đến 8 người, hợp tác đơn tuyến thận trọng, cung cấp linh tài cấp cấm chế, nguồn độc hiếm, lệnh bài thân phận giả, tần suất giao dịch khống chế không quá sáu lần mỗi năm",
    "Quân cờ vô thức": "Tu sĩ các thế lực bị Dung Đường Nguyệt dùng tinh chỉnh nhân quả dẫn dắt hành vi, không biết mình bị thao túng. Biên độ mỗi lần tinh chỉnh khống chế ở mức cánh bướm vỗ, liên tục tích lũy mấy tháng thay đổi hướng đi cục diện, suy diễn về sau đều hợp tình hợp lý, là công cụ chiến lược hạt nhân của giai đoạn ám lưu"
  },
  "Nguyên tắc": "Thành viên cốt lõi của Phần Thiên Các không được mất một ai, nhưng quân cờ vòng ngoài có thể thay bất cứ lúc nào (lời Ân Vô Quy)"
}

38.content:
{
  "Mục": "Phân giải mục tiêu chiến lược của Phần Thiên Các",
  "Đối ứng tổng cương": "Tổng cương ba giai đoạn trong tổng quan tổ chức (Ám lưu/Liệt biến/Phần Thiên) được Ngu Mạn La phân giải thành năm giai đoạn chấp hành: Ám lưu là giai đoạn thứ nhất; Liệt biến bao gồm ba đoạn Dũng Động, Kinh Đào, Phá Hiểu; Phần Thiên tức Chung Yên",
  "Giai đoạn hiện tại": "Giai đoạn thứ nhất·Ám lưu",
  "Các giai đoạn": {
    "Một·Ám lưu (hiện tại)": {
      "Mục tiêu": "Hoàn thành bố cục trong sự ẩn nấp tuyệt đối",
      "Hành động": "Thâm nhập bốn đại tông môn chính đạo (Thục Sơn Kiếm Môn, Côn Lôn Đạo Môn, Đại Lôi Âm Tự, Vạn Pháp Tông) và tầng trung của Đại Chu Tiên Triều; Dung Đường Nguyệt dùng tinh chỉnh nhân quả tạo hiềm khích giữa các tông môn; Hoắc Khỉ La ngầm khống chế ba thành thị trường linh tài Trung Ương Thần Châu; Tiêu Vận Thanh xây dựng mạng tình báo nhân mạch thượng tầng; Khương Mộ Tuyết sàng lọc người có thể chiêu mộ; toàn thể cảnh giới tăng ổn định",
      "Dấu hiệu lên giai đoạn": "Mật độ thâm nhập đạt mức có thể trong hai mươi bốn canh giờ làm tê liệt ba thành hệ thống phòng ngự vòng ngoài của bốn đại tông môn"
    },
    "Hai·Dũng Động": {
      "Mục tiêu": "Kích nổ mâu thuẫn nội bộ chính đạo bằng cách không thể truy ngược",
      "Hành động": "Dung Đường Nguyệt dẫn dắt oán hận lịch sử bùng phát tập trung; Bùi Nha Thanh ám sát nhân vật then chốt đứng ra điều đình; Liễu Nhứ Vãn thả độc tố mãn tính cấp pháp tắc vào chuỗi cung ứng của tông môn đặc định; Tô Dạ Lan bày trước pháp trận ẩn hình ở các tiết điểm địa lý then chốt",
      "Dấu hiệu lên giai đoạn": "Ít nhất hai tông môn đỉnh cấp chính đạo bùng nổ xung đột công khai không thể điều hòa"
    },
    "Ba·Kinh Đào": {
      "Mục tiêu": "Công khai can thiệp, lấy danh nghĩa Phần Thiên Các bước lên vũ đài Huyền Thiên Giới",
      "Hành động": "Ân Vô Quy kết thúc sáu nghìn năm ẩn nấp công khai lộ diện; toàn thể thành viên cốt lõi xuất chiến; bản thể bốn thú Túc Uyên, Long Quân, Lẫm Tiêu, Mộc Ly giáng thế; Thẩm Lạc Vi với thân phận Thiên Mệnh Chi Nữ sa đọa công khai đứng bên Ân Vô Quy",
      "Dấu hiệu lên giai đoạn": "Đại Chu buộc phải điều chủ lực Thần Sách Quân từ biên cảnh phía đông về Thần Đô"
    },
    "Bốn·Phá Hiểu": "Nghiền nát tàn dư chính đạo, kiến lập Phần Thiên tân trật tự. Biến số quá lớn, chỉ giữ suy diễn cấp khung, ba mươi năm trước khi bước vào mới chi tiết hóa",
    "Năm·Chung Yên": "Ân Vô Quy một mình đối mặt thiên đạo, thiêu diệt hoặc bị thiêu diệt. Thiên đạo không phải người, không thể tính toán"
  },
  "Biến số ngoại bộ cao nhất": "Sự phục hồi của Hà và sự khuếch tán của Mạch Vọng điên cuồng. Nếu Hà phục hồi hoàn toàn ở giai đoạn hai hoặc ba, Phần Thiên Các sẽ buộc phải tác chiến hai mặt trận. Quyết định của Ân Vô Quy: vấn đề của Hà để ta giải quyết, các ngươi chỉ cần đẩy kế hoạch. Đánh giá của Ngu Mạn La: Hà được Mạch Vọng điên cuồng gia trì có sức mạnh vượt xa Đại Thừa đại viên mãn, Ân Vô Quy đối kháng chính diện tỷ lệ thắng không đủ năm thành"
}
